	/**
	 * Default Constructor
	 */
    public LoanApplicationService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new LoanApplicationEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(LoanApplicationRepository.class) );
		this.validator		= applicationContext.getBean(LoanApplicationValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		LoanApplication
	 */
		public LoanApplication createLoanApplication( CreateLoanApplicationCommand command ) {

		LoanApplication entity = new LoanApplication();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setLoanApplicationId( command.getLoanApplicationId() );
            entity.setApplicationNumber( command.getApplicationNumber() );
            entity.setAmountRequested( command.getAmountRequested() );
            entity.setTermMonths( command.getTermMonths() );
            entity.setSubmittedAt( command.getSubmittedAt() );
            entity.setProduct( command.getProduct() );
            entity.setPurpose( command.getPurpose() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of LoanApplication {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateLoanApplicationCommand
	 * @return		LoanApplication
	 */
	public LoanApplication updateLoanApplication( UpdateLoanApplicationCommand command ) {

		LoanApplication entity = new LoanApplication();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setLoanApplicationId( command.getLoanApplicationId() );
            entity.setApplicationNumber( command.getApplicationNumber() );
            entity.setAmountRequested( command.getAmountRequested() );
            entity.setTermMonths( command.getTermMonths() );
            entity.setSubmittedAt( command.getSubmittedAt() );
            entity.setCustomer( command.getCustomer() );
            entity.setRiskAssessment( command.getRiskAssessment() );
            entity.setLoan( command.getLoan() );
            entity.setProduct( command.getProduct() );
            entity.setPurpose( command.getPurpose() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of LoanApplication {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteLoanApplicationCommand
	 */
	public void delete( DeleteLoanApplicationCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getLoanApplicationId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of LoanApplication {0} ", id );

	}

	/**
	 * Method to retrieve the LoanApplication via LoanApplicationFetchOneSummary
	 * @param 	summary LoanApplicationFetchOneSummary
	 * @return 	LoanApplicationFetchOneResponse
	 */
	public LoanApplication getLoanApplication( LoanApplicationFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "LoanApplicationFetchOneSummary arg cannot be null" );

		LoanApplication entity = null;
		UUID id = summary.getLoanApplicationId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a LoanApplication using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all LoanApplications
	 *
	 * @return 	List<LoanApplication>
	 */
    public List<LoanApplication> getAllLoanApplication() {
		List<LoanApplication> list = projector.findAll( new FindAllLoanApplicationQuery() );
		return list;
	}

	/**
	 * assign Customer on LoanApplication
	 * @param		command AssignCustomerToLoanApplicationCommand
	 */
	public void assignCustomer( AssignCustomerToLoanApplicationCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignCustomer(command.getLoanApplicationId(), command.getAssignment());

	}

